// Calculate today's date and 90 days in the future
const today = new Date();
const futureDate = new Date();
futureDate.setDate(today.getDate() + 90);

// Return both dates as ISO strings
return [
  {
    json: {
      startDate: today.toISOString(),
      endDate: futureDate.toISOString()
    }
  }
];

// Get input data
const items = $input.all();

// Extract property info and calendar sync contact from the first item
const propertyInfo = items[0].json.propertyInfo || {};
const calendarSyncContact = items[0].json.calendarSyncContact || {};

// Extract all events from input items
const events = items.map(item => item.json);

// Array to store detected conflicts
const conflicts = [];

// Compare all event pairs to detect conflicts
for (let i = 0; i < events.length; i++) {
  for (let j = i + 1; j < events.length; j++) {
    const event1 = events[i];
    const event2 = events[j];

    // Parse dates for comparison
    const event1Start = new Date(event1.start?.dateTime || event1.start?.date);
    const event1End = new Date(event1.end?.dateTime || event1.end?.date);
    const event2Start = new Date(event2.start?.dateTime || event2.start?.date);
    const event2End = new Date(event2.end?.dateTime || event2.end?.date);

    // Check if events overlap: event1.start < event2.end AND event1.end > event2.start
    if (event1Start < event2End && event1End > event2Start) {
      conflicts.push({
        conflict: true,
        event1: {
          id: event1.id,
          summary: event1.summary,
          start: event1.start,
          end: event1.end,
          description: event1.description
        },
        event2: {
          id: event2.id,
          summary: event2.summary,
          start: event2.start,
          end: event2.end,
          description: event2.description
        },
        propertyInfo: propertyInfo,
        calendarSyncContact: calendarSyncContact,
        detectedAt: new Date().toISOString()
      });
    }
  }
}

// Return conflicts if found, otherwise return a single item indicating no conflicts
if (conflicts.length > 0) {
  return conflicts.map(conflict => ({ json: conflict }));
} else {
  return [{ json: { 
    conflict: false, 
    propertyInfo: propertyInfo,
    calendarSyncContact: calendarSyncContact,
    message: 'No conflicts detected' 
  }}];
}

// Accumulate properties by calendar_sync_contact and format messages
const items = $input.all();
const contactGroups = {};

// Group properties by contact
for (const item of items) {
  const contact = item.json.calendar_sync_contact;
  const propertyName = item.json.property_name;
  const airbnbLink = item.json.airbnb_link || '';
  const vrboLink = item.json.vrbo_link || '';
  const bookingLink = item.json.booking_link || '';
  const calendarLink = item.json.google_calendar_link || '';
  const conflicts = item.json.conflicts || [];
  const hasConflicts = conflicts.length > 0;

  if (!contactGroups[contact]) {
    contactGroups[contact] = {
      properties: [],
      hasAnyConflicts: false
    };
  }

  contactGroups[contact].properties.push({
    name: propertyName,
    airbnbLink,
    vrboLink,
    bookingLink,
    calendarLink,
    conflicts,
    hasConflicts
  });

  if (hasConflicts) {
    contactGroups[contact].hasAnyConflicts = true;
  }
}

// Format messages for each contact
const outputItems = [];

for (const [contact, data] of Object.entries(contactGroups)) {
  let message = `🏠 *Daily Calendar Sync Reminder*

`;
  message += `Hello! Here's your daily reminder to sync calendars for your properties:

`;

  // Add properties
  for (let i = 0; i < data.properties.length; i++) {
    const prop = data.properties[i];
    message += `*${i + 1}. ${prop.name}*
`;

    // Add platform links
    if (prop.airbnbLink) message += `   📍 Airbnb: ${prop.airbnbLink}
`;
    if (prop.vrboLink) message += `   📍 Vrbo: ${prop.vrboLink}
`;
    if (prop.bookingLink) message += `   📍 Booking.com: ${prop.bookingLink}
`;
    if (prop.calendarLink) message += `   📅 Google Calendar: ${prop.calendarLink}
`;

    // Add conflict warnings if any
    if (prop.hasConflicts) {
      message += `
   ⚠️ *URGENT: CONFLICTS DETECTED!*
`;
      for (const conflict of prop.conflicts) {
        message += `   🔴 ${conflict.date}: ${conflict.platform1} vs ${conflict.platform2}
`;
      }
    }

    message += `
`;
  }

  // Add instructions
  message += `*Instructions:*
`;
  message += `1. Review each platform's calendar
`;
  message += `2. Block any new bookings on all other platforms
`;
  message += `3. Ensure all calendars are synchronized
`;

  if (data.hasAnyConflicts) {
    message += `
⚠️ *URGENT: Please resolve the conflicts highlighted above immediately to avoid double bookings!*
`;
  }

  message += `
Click the button below once you've completed the sync.`;

  outputItems.push({
    json: {
      contact: contact,
      message: message,
      propertyCount: data.properties.length,
      hasConflicts: data.hasAnyConflicts,
      properties: data.properties
    }
  });
}

return outputItems;

